const wasteApprovalThreshold = `-- name: WasteApprovalThreshold :one
select waste_approval_threshold from business_settings limit 1
`

// Sin cast: la columna es nulable (sin tope) y un cast haría que sqlc la tipara como no nulable y el
// scan tronara con el tope vacío. Sin fila de configuración, ErrNoRows: tampoco hay tope.
func (q *Queries) WasteApprovalThreshold(ctx context.Context) (*decimal.Decimal, error) {
	row := q.db.QueryRow(ctx, wasteApprovalThreshold)
	var waste_approval_threshold *decimal.Decimal
	err := row.Scan(&waste_approval_threshold)
	return waste_approval_threshold, err
}

const wasteByReason = `-- name: WasteByReason :many
select coalesce(r.merged_into_id, r.id)::bigint as reason_id, w.is_staff_meal,
       count(*)::int as records,
       coalesce(sum(w.total_cost), 0)::numeric(14,2) as total_cost,
       count(*) filter (where w.total_cost is null)::int as without_cost
  from waste_records w
  join waste_reasons r on r.id = w.reason_id
 where w.branch_id = current_branch_id() and w.status = 'applied'
   and coalesce(w.resolved_at, w.recorded_at) >= $1::timestamptz
   and coalesce(w.resolved_at, w.recorded_at) < $2::timestamptz
 group by 1, 2
 order by 4 desc
`

type WasteByReasonParams struct {
	FromTs time.Time `json:"from_ts"`
	ToTs   time.Time `json:"to_ts"`
}

type WasteByReasonRow struct {
	ReasonID    int64           `json:"reason_id"`
	IsStaffMeal bool            `json:"is_staff_meal"`
	Records     int32           `json:"records"`
	TotalCost   decimal.Decimal `json:"total_cost"`
	WithoutCost int32           `json:"without_cost"`
}

// Totales del periodo por motivo (el que queda tras juntar). Solo lo que restó: ni la por aprobar,
// ni la rechazada, ni la deshecha, ni la que cubrió un conteo. Por la fecha en que restó (la de la
// aprobación si la tuvo), como el faltante. La comida del personal por la marca copiada al registro,
// no por la del motivo de hoy.
func (q *Queries) WasteByReason(ctx context.Context, arg WasteByReasonParams) ([]WasteByReasonRow, error) {
	rows, err := q.db.Query(ctx, wasteByReason, arg.FromTs, arg.ToTs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WasteByReasonRow{}
	for rows.Next() {
		var i WasteByReasonRow
		if err := rows.Scan(
			&i.ReasonID,
			&i.IsStaffMeal,
			&i.Records,
			&i.TotalCost,
			&i.WithoutCost,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

